ssn": ["2624-8212"], "is_oa": true, "is_in_doaj": true, "is_core": true, "listed_in": ["anvur-class-a", "anvur-scientific", "cwts-core", "doaj", "jufo-1", "ki-jl-1", "norway-1", "poland-20", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310320527", "host_organization_name": "Frontiers Media", "host_organization_lineage": ["https://openalex.org/P4310320527"], "host_organization_lineage_names": ["Frontiers Media"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Frontiers in Artificial Intelligence", "raw_type": "journal-article"}, "abstract": "Current AI benchmarks often equate mimicry with genuine intelligence, emphasizing task performance over the underlying cognitive processes that enable human-like understanding. The Machine Perturbational Complexity & Agency Battery (mPCAB) introduces a new, substrate-independent framework that applies neurophysiological methods used initially to assess consciousness in artificial systems. Unlike existing evaluations, it features four key components-perturbational complexity, global workspace assessment, norm internalization, and agency-that link mechanisms with functions. This enables systematic comparisons across digital, neuromorphic, and biological substrates, addressing three research gaps: long-term reasoning with coherent behavior, norm internalization amid distribution shifts, and transformational creativity involving meta-cognitive rule modification. By analyzing theories of consciousness (GNW, IIT, PP, HOT), we identify targets for AI implementation. Our cognitive architecture analysis maps human functions-such as working memory and executive control-to their computational counterparts, providing guiding principles for design. The creativity taxonomy progresses from combinational to transformational, with measurable criteria like changes in conceptual space and the depth of meta-level reasoning. Ethical considerations are integrated into frameworks for monitoring organoid intelligence, reducing bias in creativity, and addressing rights issues. Pilot studies demonstrate mPCAB's feasibility across different substrates and show that its metrics are comparable. This framework moves evaluation away from superficial benchmarks toward mechanism-based assessment, supporting the development of mind-like machines and responsible AI advancements."}]", "excerpt_truncated": true, "source_sha256": "117056e7d708e27e410c194a1b6c5be6d6e7e498f8fce56ba4be72450ab56132", "verification_required": true, "topic_domain": "memory_and_identity", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1038/npp.2010.169", "doi:10.20381/ruor-5367", "openalex:W2038680295", "openalex:W2518653487"], "source_candidates": ["https://doi.org/10.1038/npp.2010.169", "https://www.nature.com/articles/npp2010169.pdf", "https://doi.org/10.20381/ruor-5367"], "source_candidate_identities": {}}

